create table if not exists instituto.normas(id text primary key, artigo text, ementa text, capitulo text, urn text, fonte text not null);
create table if not exists instituto.precedentes(id text primary key, orgao text, especie text, tese text, fonte text not null);
create table if not exists instituto.teses(id text primary key, tese text not null);
create table if not exists instituto.assunto_norma(assunto int, norma text references instituto.normas, natureza text, primary key(assunto,norma));
create table if not exists instituto.classe_norma(classe text, norma text references instituto.normas, primary key(classe,norma));
create table if not exists instituto.tese_norma(tese text references instituto.teses, norma text references instituto.normas, primary key(tese,norma));
create table if not exists instituto.precedente_norma(precedente text references instituto.precedentes, norma text references instituto.normas, primary key(precedente,norma));
create table if not exists instituto.tese_precedente(tese text references instituto.teses, precedente text references instituto.precedentes, primary key(tese,precedente));
create table if not exists instituto.assunto_tese(assunto int, tese text references instituto.teses, primary key(assunto,tese));
alter table instituto.normas enable row level security;
alter table instituto.precedentes enable row level security;
alter table instituto.teses enable row level security;
alter table instituto.assunto_norma enable row level security;
alter table instituto.classe_norma enable row level security;
alter table instituto.tese_norma enable row level security;
alter table instituto.precedente_norma enable row level security;
alter table instituto.tese_precedente enable row level security;
alter table instituto.assunto_tese enable row level security;
