insert into instituto.precedentes values ('P-STJ-S214','STJ','Súmula 214','O fiador na locação não responde por obrigações resultantes de aditamento ao qual não anuiu.','https://scon.stj.jus.br/SCON/sumstj/'),('P-STJ-S268','STJ','Súmula 268','O fiador que não integrou a relação processual na ação de despejo não responde pela execução do julgado.','https://scon.stj.jus.br/SCON/sumstj/'),('P-STJ-S335','STJ','Súmula 335','Nos contratos de locação, é válida a cláusula de renúncia à indenização das benfeitorias e ao direito de retenção.','https://scon.stj.jus.br/SCON/sumstj/'),('P-STJ-S549','STJ','Súmula 549','É válida a penhora de bem de família pertencente a fiador de contrato de locação.','https://scon.stj.jus.br/SCON/sumstj/'),('P-STF-T295','STF','Tema 295 (RE 612.360)','Constitucional a penhora do bem de família do fiador de locação.','https://portal.stf.jus.br/jurisprudenciaRepercussao/'),('P-STF-T1127','STF','Tema 1127 (RE 1.307.334)','É constitucional a penhora de bem de família do fiador de contrato de locação comercial.','https://portal.stf.jus.br/jurisprudenciaRepercussao/') on conflict do nothing;
insert into instituto.teses values ('T01','Falta de pagamento autoriza despejo; purgação da mora evita a rescisão'),('T02','Liminar de desocupação em 15 dias mediante caução de três aluguéis'),('T03','Denúncia vazia após 30 meses (residencial) ou fim do prazo (não residencial)'),('T04','Retomada para uso próprio ou de familiar'),('T05','Aluguel revisto ao preço de mercado após três anos'),('T06','Renovação compulsória da locação empresarial'),('T07','Consignação do aluguel ou das chaves libera o locatário'),('T08','Indenização ou retenção por benfeitorias (renunciável)'),('T09','Preterição da preferência gera perdas e danos ou adjudicação'),('T10','Fiança: alcance, exoneração e penhora do bem de família do fiador'),('T11','Multa por devolução antecipada proporcional ao prazo restante'),('T12','Encargos de condomínio: ordinárias do locatário, extraordinárias do locador'),('T13','Cobrança de aluguéis por execução de título') on conflict do nothing;
